import type { Unknown } from './unknowable.ts';

export interface RecapRequest {
    readonly previous: string;
    readonly excerpt: string;
    readonly words: number;
    /** the agents whose transcripts the excerpt interleaves, e.g. 'claude in w1:p1 — Victoria cutover' */
    readonly lanes: readonly string[];
}

export type Written = { readonly kind: 'written'; readonly markdown: string; readonly costUsd: number } | Unknown;

export interface Summarizer {
    readonly backend: string;
    write(request: RecapRequest): Promise<Written>;
}
import type { Lane } from '#src/recap/domain/lane.ts';
import type { Unknown } from './unknowable.ts';

export interface Entry {
    readonly role: 'user' | 'agent' | 'tool';
    readonly text: string;
}

export interface Chunk {
    readonly kind: 'chunk';
    readonly entries: readonly Entry[];
    readonly title: string | null;
    readonly lastPrompt: string | null;
    readonly claudeRecap: string | null;
    /** the byte after the last complete line read: the next cursor */
    readonly end: number;
    readonly size: number;
}

export type Located = { readonly kind: 'located'; readonly path: string; readonly size: number } | Unknown;

export type ChunkResult = Chunk | Unknown;

/** One adapter per agent kind; each knows where its transcripts live and how to read them. */
export interface Transcripts {
    readonly agent: string;
    locate(lane: Lane): Located;
    read(path: string, from: number, budget: number): ChunkResult;
}
import { mkdirSync } from 'node:fs';
import type { RecapRequest, Summarizer, Written } from '#src/ports/summarizer.ts';
import { unknown } from '#src/ports/unknowable.ts';
import { duration } from '#src/recap/domain/time.ts';
import { instructions, message, unfenced } from './recap-prompt.ts';
import { run, scrubbedEnv } from './run.ts';

function resultOf(stdout: string): { text: string; cost: number } | null {
    try {
        const parsed: unknown = JSON.parse(stdout);
        if (typeof parsed !== 'object' || parsed === null) {
            return null;
        }
        const fields = parsed as Readonly<Record<string, unknown>>;
        const text = fields['result'];
        const cost = fields['total_cost_usd'];
        return typeof text === 'string' ? { text, cost: typeof cost === 'number' ? cost : 0 } : null;
    } catch {
        return null;
    }
}

/**
 * Headless Claude Code on the operator's subscription (`--bare` would need an API key).
 * No tools, no settings (so no hooks), no MCP, and no transcript of its own.
 */
export class ClaudeSummarizer implements Summarizer {
    readonly backend: string;
    private readonly model: string;
    private readonly workDir: string;
    private readonly timeoutMs: number;

    constructor(model: string, workDir: string, timeoutMs: number) {
        this.model = model === '' ? 'haiku' : model;
        this.backend = `claude/${this.model}`;
        this.workDir = workDir;
        this.timeoutMs = timeoutMs;
    }

    async write(request: RecapRequest): Promise<Written> {
        mkdirSync(this.workDir, { recursive: true });
        const args = [
            '-p', '--model', this.model, '--no-session-persistence', '--tools', '', '--setting-sources', '',
            '--strict-mcp-config', '--output-format', 'json', '--system-prompt', instructions(request.words),
        ];
        const ran = await run('claude', args, { input: message(request), timeoutMs: this.timeoutMs, cwd: this.workDir, env: scrubbedEnv() });
        if (ran.timedOut) {
            return unknown({ why: 'timeout', after: duration(this.timeoutMs) });
        }
        const result = resultOf(ran.stdout);
        if (ran.code !== 0 || result === null) {
            return unknown({ why: 'failed', code: ran.code, detail: (ran.stderr || ran.stdout).trim().slice(0, 300) });
        }
        return { kind: 'written', markdown: unfenced(result.text), costUsd: result.cost };
    }
}
import { mkdirSync, readFileSync, rmSync } from 'node:fs';
import { join } from 'node:path';
import type { RecapRequest, Summarizer, Written } from '#src/ports/summarizer.ts';
import { unknown } from '#src/ports/unknowable.ts';
import { duration } from '#src/recap/domain/time.ts';
import { instructions, message, unfenced } from './recap-prompt.ts';
import { run, scrubbedEnv } from './run.ts';

/** `codex exec`, ephemeral (no rollout written), read-only sandbox, user config ignored. */
export class CodexSummarizer implements Summarizer {
    readonly backend: string;
    private readonly model: string;
    private readonly workDir: string;
    private readonly timeoutMs: number;

    constructor(model: string, workDir: string, timeoutMs: number) {
        this.model = model;
        this.backend = model === '' ? 'codex' : `codex/${model}`;
        this.workDir = workDir;
        this.timeoutMs = timeoutMs;
    }

    async write(request: RecapRequest): Promise<Written> {
        mkdirSync(this.workDir, { recursive: true });
        const out = join(this.workDir, `codex-${process.pid}-${Date.now()}.md`);
        const args = [
            'exec', '--ephemeral', '--skip-git-repo-check', '--ignore-user-config', '-s', 'read-only',
            '--color', 'never', ...(this.model === '' ? [] : ['-m', this.model]), '-o', out, '-',
        ];
        const input = `${instructions(request.words)}\n\n${message(request)}`;
        const ran = await run('codex', args, { input, timeoutMs: this.timeoutMs, cwd: this.workDir, env: scrubbedEnv() });
        let text = '';
        try { text = readFileSync(out, 'utf8'); } catch { /* codex wrote nothing */ }
        rmSync(out, { force: true });
        if (ran.timedOut) {
            return unknown({ why: 'timeout', after: duration(this.timeoutMs) });
        }
        if (ran.code !== 0 || text.trim() === '') {
            return unknown({ why: 'failed', code: ran.code, detail: ran.stderr.trim().slice(-300) });
        }
        return { kind: 'written', markdown: unfenced(text), costUsd: 0 };
    }
}
import type { RecapRequest } from '#src/ports/summarizer.ts';

/** The recap's fixed shape. Every backend gets the same instructions. */
export function instructions(words: number): string {
    return [
        'You keep a running recap of ONE terminal tab. The tab may hold several coding agents working',
        'side by side; the recap covers all of them as one piece of work. It is shown in a tall, narrow',
        'column beside them so the operator never loses track of what is going on in this tab.',
        '',
        'Rewrite the recap from the PREVIOUS RECAP plus the NEW TRANSCRIPT EXCERPT (one === section per',
        'agent). When there are several agents, say which one did what by its short label. Output ONLY',
        'Markdown, no preamble, using exactly these sections in this order (omit a section only if empty):',
        '',
        '## Goal            — what the operator ultimately wants, 1-3 bullets',
