    setInterval(() => {
        informer.resync();
        void heal(bridge);
    }, RESYNC_MS).unref();
    log(`daemon ${process.pid} up, state in ${root}`);
    await informer.enterSubscription();
    await informer.run();
    pidfile.release(process.pid);
    return 0;
}

