// Reads atalaya-bridge's outbox and heartbeat (never writes them) and heals the
// service when its heartbeat has gone stale. The one action taken on the bridge.
import { readFileSync, statSync } from 'node:fs';
import { join } from 'node:path';
import type { Alert, Bridge, HealResult, ReadingResult } from '#src/ports/bridge.ts';
import { unknown } from '#src/ports/unknowable.ts';
import { obj, parse, str } from './jsonl.ts';
import { run } from './run.ts';

const UNIT = 'atalaya-bridge.service';
const STALE_MS = 180_000;
const HEAL_EVERY_MS = 300_000;

function alertOf(line: string): [string, Alert] | null {
    const row = parse(line);
    const episode = obj(row?.['episode']);
