import { laneStatus } from '#src/recap/domain/status.ts';
import type { LaneStatus } from '#src/recap/domain/status.ts';
import type { Alert } from '#src/ports/bridge.ts';
import type { LaneCursor, TabLane, TabRecap, TabView } from '#src/ports/recap-store.ts';
import { ago, plainMarkdown, style, wrap } from './wrap.ts';

export type BridgeView =
    | { readonly kind: 'absent' }
    | { readonly kind: 'present'; readonly heartbeatAgeMs: number | null; readonly alerts: ReadonlyMap<string, Alert> };

export interface ColumnView {
    readonly tab: TabView | null;
    readonly recap: TabRecap | null;
    readonly bridge: BridgeView;
    readonly now: number;
}

export type Markdown = (markdown: string, width: number) => readonly string[] | null;

const STALE_BEAT_MS = 180_000;
const PROMPT_LINES = 2;

export function badge(status: LaneStatus): string {
    switch (status) {
        case 'working':
            return style.yellow('● working');
        case 'blocked':
            return style.red('● blocked — needs you');
        case 'idle':
            return style.green('● idle');
        case 'done':
            return style.green('● done');
        case 'unknown':
            return style.gray('● unknown');
        default: {
            const exhaustive: never = status;
            return String(exhaustive);
        }
    }
}

function alertLines(bridge: BridgeView, pane: string, now: number, width: number): string[] {
    const alert = bridge.kind === 'present' ? bridge.alerts.get(pane) : undefined;
    if (alert === undefined) {
        return [];
    }
    const work = [alert.branch, alert.unmerged === null ? null : `${alert.unmerged} unmerged`, alert.tree].filter((part) => part !== null);
    return wrap(`⚑ ${alert.kind} ${ago(now - alert.at)} ago${work.length > 0 ? ` · ${work.join(' · ')}` : ''}`, width, '  ').map(style.blue);
}

function promptLines(cursor: LaneCursor | undefined, width: number): string[] {
    const prompt = cursor?.lastPrompt ?? null;
    return prompt === null ? [] : wrap(`› ${prompt.split('\n').join(' ')}`, width, '  ').slice(0, PROMPT_LINES).map(style.dim);
}

/** Who is in the tab: one short header per lane. The recap below is the tab's, not the lane's. */
function laneHeader(lane: TabLane, view: ColumnView, width: number): string[] {
    const cursor = view.recap?.lanes.find((c) => c.pane === lane.pane);
    const title = cursor?.title ?? lane.title ?? lane.pane;
    return [
        ...wrap(title, width).map((line) => style.bold(line)),
        ...wrap([badge(laneStatus(lane.status)), style.gray(`${lane.agent} ${lane.pane}`)].join(style.gray(' · ')), width, '  '),
        ...alertLines(view.bridge, lane.pane, view.now, width),
        ...promptLines(cursor, width),
    ];
}

function recapMeta(recap: TabRecap | null, now: number, width: number): string[] {
    const at = recap?.at ?? null;
    const parts = [
        style.bold(style.cyan('TAB RECAP')),
        at === null ? null : style.gray(`${ago(now - at)} ago`),
        recap?.backend ?? null,
        recap?.running === true ? style.magenta('⟳ updating') : null,
    ].filter((part) => part !== null);
    return wrap(parts.join(style.gray(' · ')), width, '  ');
}

function body(recap: TabRecap | null, width: number, markdown: Markdown): string[] {
    if (recap !== null && recap.markdown !== '') {
        return [...(markdown(recap.markdown, width) ?? plainMarkdown(recap.markdown, width))];
    }
    const theirs = (recap?.lanes ?? []).flatMap((c) => (c.claudeRecap === null ? [] : [c.claudeRecap]));
    if (theirs.length > 0) {
        return [style.gray("Claude's own recap, until the tab's is written:"), ...theirs.flatMap((text) => wrap(text, width).map(style.italic))];
    }
    return wrap('No recap yet. It is written when an agent in this tab finishes a turn — press r to write it now.', width).map(style.gray);
}

function errorLines(recap: TabRecap | null, width: number): string[] {
    const error = recap?.error ?? null;
    return error === null ? [] : ['', ...wrap(`recap: ${error}`, width).map(style.red)];
}

function bridgeWarning(bridge: BridgeView, width: number): string[] {
    if (bridge.kind === 'absent' || bridge.heartbeatAgeMs === null || bridge.heartbeatAgeMs < STALE_BEAT_MS) {
        return [];
    }
    return [...wrap(`atalaya-bridge silent for ${ago(bridge.heartbeatAgeMs)} — healing`, width).map(style.red), ''];
}

/** The whole column, as lines: who is in the tab, then the tab's one recap. Total; no I/O. */
export function present(view: ColumnView, width: number, markdown: Markdown): string[] {
    if (view.tab === null || view.tab.lanes.length === 0) {
        return wrap('Waiting for an agent in this tab…', width).map(style.gray);
    }
    const headers = view.tab.lanes.flatMap((lane, index) => [...(index > 0 ? [''] : []), ...laneHeader(lane, view, width)]);
    return [
        ...bridgeWarning(view.bridge, width),
        ...headers,
        '',
        style.gray('─'.repeat(width)),
        ...recapMeta(view.recap, view.now, width),
        '',
        ...body(view.recap, width, markdown),
        ...errorLines(view.recap, width),
    ];
}

export type Mode = 'column' | 'modal' | 'bar';

const HINTS: Readonly<Record<Mode, readonly string[]>> = {
    column: ['tap: full screen · r recap now · j/k scroll', 'tap: full screen · r · j/k', 'r recap · j/k', 'r'],
    modal: ['q close · r recap now · j/k scroll · g top', 'q close · r recap now · j/k', 'q close · r · j/k', 'q'],
    bar: [],
};

/** The longest hint that fits: a cut-off hint reads as a bug. */
export function footer(width: number, mode: Mode): string {
    return style.gray(HINTS[mode].find((hint) => hint.length <= width) ?? '');
}

const PLAIN_BULLET = /^\s*[-*+]\s+/;

/** The first bullet of a recap section, in plain text. */
export function firstItem(markdown: string, section: string): string | null {
    let inside = false;
    for (const line of markdown.split('\n')) {
        if (line.startsWith('#')) {
            inside = line.replace(/^#+\s*/, '').toLowerCase().startsWith(section.toLowerCase());
