import type { Unknown } from './unknowable.ts';

/** One labelled line-group an extension attaches to a lane, shown under the lane's header. */
export interface Note {
    readonly label: string;
    readonly at: number | null;
    readonly details: readonly string[];
}

export type NotesResult = { readonly kind: 'notes'; readonly byPane: ReadonlyMap<string, readonly Note[]> } | Unknown;

export type UpkeepResult = { readonly kind: 'idle' } | { readonly kind: 'acted'; readonly saying: string } | Unknown;

/** An optional add-on. Every member is optional: the plugin works with none loaded. */
export interface Extension {
    readonly id: string;
    notes?(): NotesResult;
    warning?(): string | null;
    upkeep?(): Promise<UpkeepResult>;
}

/** Returns null when the extension does not apply; reads its configuration through `get`, at call time. */
export type ExtensionFactory = (get: (key: string) => string | undefined) => Extension | null;
import type { ExtensionFactory } from '#src/ports/extension.ts';

export const FACTORIES: readonly ExtensionFactory[] = [];
import type { Extension, Note } from '#src/ports/extension.ts';
import { isUnknown } from '#src/ports/unknowable.ts';
import { FACTORIES } from './index.ts';

export function loadExtensions(get: (key: string) => string | undefined): readonly Extension[] {
    return FACTORIES.flatMap((factory) => factory(get) ?? []);
}

/** Every extension's notes, merged per pane in factory order; a failing extension adds none. */
export function notesOf(extensions: readonly Extension[]): ReadonlyMap<string, readonly Note[]> {
    const merged = new Map<string, readonly Note[]>();
    for (const extension of extensions) {
        const result = extension.notes?.();
        if (result === undefined || isUnknown(result)) {
            continue;
        }
        for (const [pane, notes] of result.byPane) {
            merged.set(pane, [...(merged.get(pane) ?? []), ...notes]);
        }
    }
    return merged;
}

export function warningsOf(extensions: readonly Extension[]): readonly string[] {
    return extensions.flatMap((extension) => extension.warning?.() ?? []);
}
import type { Extension } from '#src/ports/extension.ts';
import { isUnknown, saying } from '#src/ports/unknowable.ts';

/** One upkeep pass over every extension; never throws, so one bad extension cannot stop the tick. */
export async function upkeep(extensions: readonly Extension[], log: (line: string) => void): Promise<void> {
    for (const extension of extensions) {
        try {
            const done = await extension.upkeep?.();
            if (done === undefined || done.kind === 'idle') {
                continue;
            }
            log(isUnknown(done) ? `${extension.id} upkeep failed: ${saying(done.why)}` : `${extension.id}: ${done.saying}`);
        } catch (error) {
            log(`${extension.id} upkeep threw: ${error instanceof Error ? error.message : String(error)}`);
        }
    }
}
