import { join } from 'node:path';
import { ClaudeSummarizer } from '#src/adapters/claude-summarizer.ts';
import { CodexSummarizer } from '#src/adapters/codex-summarizer.ts';
import { CustomSummarizer } from '#src/adapters/custom-summarizer.ts';
import { HermesSummarizer } from '#src/adapters/hermes-summarizer.ts';
import { OpencodeSummarizer } from '#src/adapters/opencode-summarizer.ts';
import type { Harnesses, HarnessesResult } from '#src/ports/harnesses.ts';
import type { Notifier } from '#src/ports/notifier.ts';
import type { Summarizer, Written } from '#src/ports/summarizer.ts';
import { isUnknown, saying, unknown } from '#src/ports/unknowable.ts';
import { loadConfig } from './config.ts';
import type { BackendChoice, BackendId, Config } from './config.ts';

/** What `auto` tries, in this order. `custom` is never automatic: it exists only when named. */
export const AUTO_ORDER: readonly BackendId[] = ['claude', 'codex', 'opencode', 'hermes'];

type Make = (config: Config, work: string) => Summarizer;

const MAKERS: Readonly<Record<BackendId, Make>> = {
    claude: (config, work) => new ClaudeSummarizer(config.models.claude, work, config.timeoutMs),
    codex: (config, work) => new CodexSummarizer(config.models.codex, work, config.timeoutMs),
    opencode: (config, work) => new OpencodeSummarizer(config.models.opencode, work, config.timeoutMs),
    hermes: (config, work) => new HermesSummarizer(config.models.hermes, work, config.timeoutMs),
    custom: (config, work) => new CustomSummarizer(config.customCommand, work, config.timeoutMs),
};

/** Herdr's list and the PATH must both say yes; when herdr cannot be asked, the PATH alone decides. */
export function intersect(fromHerdr: HarnessesResult, fromPath: HarnessesResult): HarnessesResult {
    if (isUnknown(fromPath)) {
        return fromHerdr;
    }
    return isUnknown(fromHerdr) ? fromPath : { kind: 'available', ids: fromPath.ids.filter((id) => fromHerdr.ids.includes(id)) };
}

/** The backend to run: the one named, or for `auto` the first of AUTO_ORDER that is available; null = none. */
export function pick(choice: BackendChoice, available: readonly string[]): BackendId | null {
    return choice === 'auto' ? (AUTO_ORDER.find((id) => available.includes(id)) ?? null) : choice;
}

const NONE = 'a coding agent to write recaps: install claude, codex, opencode or hermes (or set TAB_RECAP_BACKEND / TAB_RECAP_CUSTOM_CMD)';

class Nothing implements Summarizer {
    readonly backend = 'none';
    write(): Promise<Written> {
        return Promise.resolve(unknown({ why: 'not-found', what: NONE }));
    }
}

/**
 * Picks the summarizer for each recap. The configuration is re-read every time (a switch applies at once);
 * what is installed is looked up at start and on every resync and cached, so `summarizer()` stays synchronous.
 */
export class Backends {
    private available: readonly string[] = [];
    private warned = false;
    private readonly work: string;
    private readonly sources: { readonly herdr: Harnesses; readonly path: Harnesses };
    private readonly notifier: Notifier;
    private readonly log: (line: string) => void;

    constructor(root: string, sources: { readonly herdr: Harnesses; readonly path: Harnesses }, notifier: Notifier, log: (line: string) => void) {
        this.work = join(root, 'summarizer');
        this.sources = sources;
        this.notifier = notifier;
        this.log = log;
    }

    async refresh(): Promise<void> {
        const found = intersect(await this.sources.herdr.available(), await this.sources.path.available());
        if (isUnknown(found)) {
            this.log(`harness lookup failed: ${saying(found.why)}`);
            return;
        }
        this.available = found.ids;
        await this.warnWhenNone();
    }

    /** One toast per daemon start, and only when `auto` has nothing to choose from. */
    private async warnWhenNone(): Promise<void> {
        if (this.warned || loadConfig().backend !== 'auto' || pick('auto', this.available) !== null) {
            return;
        }
        this.warned = true;
        this.log(`no backend: ${NONE}`);
        await this.notifier.notify('Tab Recap', `No recap writer found — ${NONE}`);
    }

    summarizer(): Summarizer {
        const config = loadConfig();
        const id = pick(config.backend, this.available);
        return id === null ? new Nothing() : MAKERS[id](config, this.work);
    }
}
import { mkdirSync } from 'node:fs';
import type { RecapRequest, Summarizer, Written } from '#src/ports/summarizer.ts';
import { unknown } from '#src/ports/unknowable.ts';
import { duration } from '#src/recap/domain/time.ts';
import { instructions, message, unfenced } from './recap-prompt.ts';
import { obj, parse, str } from './jsonl.ts';
import { run, scrubbedEnv } from './run.ts';

/** No tool, no permission: measured, the request shrinks from ~9k to <1k tokens and no tool event appears. */
const TOOLLESS = JSON.stringify({ tools: { '*': false }, permission: { '*': 'deny' } });

export function opencodeArgs(model: string): string[] {
    return ['run', '--pure', '--format', 'json', ...(model === '' ? [] : ['-m', model])];
}

export interface OpencodeOutput {
    readonly text: string;
    readonly cost: number;
    readonly session: string | null;
}

/** `--format json` is one event per line: the answer is the `text` parts, the cost the `step_finish` parts. */
export function opencodeOutput(stdout: string): OpencodeOutput {
    let text = '';
    let cost = 0;
    let session: string | null = null;
    for (const line of stdout.split('\n')) {
        const event = parse(line);
        if (event === null) {
            continue;
        }
        session = str(event['sessionID']) ?? session;
        const part = obj(event['part']);
        if (event['type'] === 'text' && typeof part['text'] === 'string') {
            text += part['text'];
        }
        if (event['type'] === 'step_finish' && typeof part['cost'] === 'number') {
            cost += part['cost'];
        }
    }
    return { text, cost, session };
}

/**
 * `opencode run`, prompt on stdin, tools and permissions denied, plugins off. opencode has no
 * ephemeral flag, so the session it stored is deleted once the answer is read.
 */
export class OpencodeSummarizer implements Summarizer {
    readonly backend: string;
    private readonly model: string;
    private readonly workDir: string;
    private readonly timeoutMs: number;

    constructor(model: string, workDir: string, timeoutMs: number) {
        this.model = model;
        this.backend = model === '' ? 'opencode' : `opencode/${model}`;
        this.workDir = workDir;
        this.timeoutMs = timeoutMs;
    }

    async write(request: RecapRequest): Promise<Written> {
        mkdirSync(this.workDir, { recursive: true });
        const env = { ...scrubbedEnv(), OPENCODE_CONFIG_CONTENT: TOOLLESS };
        const input = `${instructions(request.words)}\n\n${message(request)}`;
        const ran = await run('opencode', opencodeArgs(this.model), { input, timeoutMs: this.timeoutMs, cwd: this.workDir, env });
        const output = opencodeOutput(ran.stdout);
        if (output.session !== null) {
            await run('opencode', ['session', 'delete', output.session], { input: '', timeoutMs: 30_000, cwd: this.workDir, env });
        }
        if (ran.timedOut) {
            return unknown({ why: 'timeout', after: duration(this.timeoutMs) });
        }
        if (ran.code !== 0 || output.text.trim() === '') {
            return unknown({ why: 'failed', code: ran.code, detail: (ran.stderr || ran.stdout).trim().slice(0, 300) });
        }
        return { kind: 'written', markdown: unfenced(output.text), costUsd: output.cost };
    }
}
