from typing import Any

from gitlab_client import GitLabClient
from litellm_client import LiteLLMClient
from service import add_highlights

OBJECT_KIND = "release"
CREATE_ACTION = "create"

SYSTEM_PROMPT = (
    "You write concise release-note highlights for a homelab software project. "
    "From the list of merged changes (Conventional Commit subjects) since the "
    "previous release, produce 3 to 6 markdown bullet points, user-impact "
    "oriented, no preamble, no headings, and do not restate the version number. "
    "Keep each bullet short. If nothing is user-facing, say so in a single bullet."
)


class _Highlighter:
    """Adapts the shared, generic LiteLLM client to the release Highlighter port."""

    def __init__(self, llm: LiteLLMClient) -> None:
        self._llm = llm

    def generate(self, commit_lines: list[str]) -> str:
        user_content = "Merged changes since the previous release:\n" + "\n".join(commit_lines)
        return self._llm.complete(SYSTEM_PROMPT, user_content)


def handle(body: dict[str, Any]) -> str:
    if body.get("action") != CREATE_ACTION:
        return "ignored"
    project = body.get("project") or {}
    project_id = project.get("id")
    tag = body.get("tag")
    if not isinstance(project_id, int) or not isinstance(tag, str) or not tag:
        return "invalid-payload"
    return add_highlights(project_id, tag, GitLabClient(), _Highlighter(LiteLLMClient()))
